def _fit(train, inputs, dt, time):
    from scipy.optimize import least_squares
    complete = np.isfinite(train['coupon_features_raw']).all(axis=1)
    if complete.sum() < 12:
        complete[:] = True
    inputs = tuple((a[complete] for a in inputs))
    inc = (train['strain_curves_obs'] - train['strain_0'][:, None])[complete]
    y = np.r_[inc.ravel(), train['instant_rate_obs'][complete]]
    width = inputs[-1].shape[1] + 2

    def design(taus):
        a, b = _design(taus, inputs, dt, time)
        return np.vstack((a.reshape(-1, width), b))

    def unpack(p):
        return np.array([p[0], p[0] + (24.99 - p[0]) * p[1]])

    def residual(p):
        return np.einsum('ij,j->i', design(unpack(p)), p[2:]) - y
    bounds = (np.r_[0.051, 1e-05, np.full(width, -np.inf)], np.r_[24.98, 1.0, np.full(width, np.inf)])
    fits = []
    for fast, slow in ((0.35, 2.0), (0.65, 4.5), (1.1, 8.0), (2.0, 14.0)):
        A = design([fast, slow])
        start = np.r_[fast, (slow - fast) / (24.99 - fast), np.linalg.lstsq(A, y, rcond=None)[0]]
        fits.append(least_squares(residual, start, bounds=bounds, loss='soft_l1', f_scale=0.04, max_nfev=100))
    p = min(fits, key=lambda fit: fit.cost).x
    for _ in range(2):
        e = residual(p)
        scale = np.r_[np.full(inc.size, 2.5 * _mad(e[:inc.size])), np.full(inc.shape[0], 2.5 * _mad(e[inc.size:]))]
        p = least_squares(lambda q: residual(q) / scale, p, bounds=bounds, loss='cauchy', max_nfev=100).x
    return (unpack(p), p[2:])

def _check_panels(value):
    if isinstance(value, dict):
        if {'lab_id', 'cmd_stress', 'true_stress'} <= value.keys():
            yield value
        for key in ('dataset', 'calibration_load_cells'):
            if key in value:
                yield from _check_panels(value[key])
    elif isinstance(value, (list, tuple)):
        for item in value:
            yield from _check_panels(item)
